get_product_listing.code:
const response = await client.productListing.getProductListing();
const settings = response.map.product_listing;
console.log(settings.sorting.enabled, settings.sorting.sort_by);
console.log(settings.load.type, settings.load.pagination.per_page);

patch_product_listing.code:
const response = await client.productListing.patchProductListing({
    product_listing: {sorting: {enabled: true, sort_by: 'price_asc'}, load: {pagination: {per_page: 24}}},
});
const settings = response.map.product_listing;
console.log(settings.sorting.sort_by, settings.load.pagination.per_page);
